package vn.edu.eaut.lab6.controller; import jakarta.servlet.*;import jakarta.servlet.annotation.WebServlet;import jakarta.servlet.http.*;import java.io.*;import java.util.*;import vn.edu.eaut.lab6.store.StudentStore;@WebServlet("/dashboard") public class DashboardServlet extends HttpServlet{protected void doGet(HttpServletRequest q,HttpServletResponse p)throws ServletException,IOException{Map<String,Integer> m=new LinkedHashMap<>();for(String c:StudentStore.classes())m.put(c,StudentStore.countByClass(c));q.setAttribute("total",StudentStore.count());q.setAttribute("byClass",m);q.getRequestDispatcher("/dashboard.jsp").forward(q,p);}}
